from fastembed import TextEmbedding
from qdrant_client import QdrantClient
from qdrant_client.models import Distance, PointStruct, VectorParams

# 1. Initialize Qdrant Client (Targeting port 6333 from docker mapping)
client = QdrantClient(host="localhost", port=6333)

COLLECTION_NAME = "news_embeddings"
# Jina V2 supports 8,192 tokens (~32k+ characters)
MODEL_NAME = "jinaai/jina-embeddings-v2-base-en"
VECTOR_SIZE = 768

# 2. Initialize embedding model
embedding_model = TextEmbedding(model_name=MODEL_NAME)


def init_collection():
    """Create Qdrant collection if it doesn't already exist."""
    collections = [c.name for c in client.get_collections().collections]
    if COLLECTION_NAME not in collections:
        client.create_collection(
            collection_name=COLLECTION_NAME,
            vectors_config=VectorParams(
                size=VECTOR_SIZE,
                distance=Distance.COSINE,  # Cosine similarity for score filtering
            ),
        )
        print(
            f"Collection '{COLLECTION_NAME}' created with vector size {VECTOR_SIZE}."
        )


def upsert_news(news_id: int | str, content: str):
    """Reusable function to embed news content and store/update it in Qdrant.

    - news_id is set as the Point ID and stored in the payload.
    - content vector is generated via ONNX model.
    """
    # Generate embedding vector
    vector = list(embedding_model.embed([content]))[0].tolist()

    # Upload point to Qdrant
    client.upsert(
        collection_name=COLLECTION_NAME,
        points=[
            PointStruct(
                id=news_id, vector=vector, payload={"content": content}
            )
        ],
    )
    print(f"Successfully upserted news ID: {news_id}")


def search_matching_news(
    content: str, threshold: float = 0.80
) -> list[dict]:
    """Retrieves News IDs and similarity scores for documents matching at least 80% (0.80 score)."""
    # Embed query text
    query_vector = list(embedding_model.embed([content]))[0].tolist()

    # Perform similarity search filtering by 80% score threshold directly in Qdrant engine
    results = client.query_points(
        collection_name=COLLECTION_NAME,
        query=query_vector,
        score_threshold=threshold,  # 80% similarity threshold
        limit=10,
    ).points

    matches = []
    for hit in results:
        matches.append(
            {
                "news_id": hit.id,
                "similarity_score": round(hit.score, 4),
                "content": hit.payload.get("content"),
            }
        )

    return matches


# ==========================================
# Script Execution
# ==========================================
